const GLOBAL_CSS = `
  *, *::before, *::after { box-sizing:border-box; margin:0; padding:0;
    transition:background-color 0.25s ease,border-color 0.25s ease,color 0.25s ease; }
  :root {
    font-size:16px;
    --text-sm:0.875rem; --text-base:1rem; --text-h3:1.25rem; --text-h2:1.563rem; --text-h1:1.953rem;
    --sp-1:8px; --sp-2:16px; --sp-3:24px; --sp-4:32px; --sp-6:48px; --sp-8:64px;
    --ff-sans:'IBM Plex Sans',-apple-system,sans-serif;
    --ff-mono:'IBM Plex Mono',monospace;
  }
  [data-theme="dark"] {
    --c-base:#000000; --c-surface:#0D0D0D; --c-surface-2:#141414; --c-border:#1F1F1F;
    --c-secondary:#5B9BD5; --c-secondary-lt:#0A1520;
    --c-accent:#FF6B52; --c-accent-lt:#1A0A08;
    --c-text:#F0EDEA; --c-text-muted:#888580; --c-text-subtle:#555250;
    --c-success:#3DD68C; --c-success-lt:#040F09;
    --c-warning:#F5A623; --c-warning-lt:#120A00;
    --c-error:#FF6B6B; --c-error-lt:#130404;
    --c-chart-bar:#5B9BD5; --c-chart-bar2:#1F2D3D; --c-toggle-knob:#F0EDEA;
    --c-bullet-poor:#404040; --c-bullet-mid:#282828; --c-bullet-good:#1E1E1E;
    --c-bullet-border:#2A2A2A; --c-bullet-bar:#7DB5E5;
  }
  [data-theme="light"] {
    --c-base:#F7F6F3; --c-surface:#FFFFFF; --c-surface-2:#EFEEE9; --c-border:#E2DFD8;
    --c-secondary:#2C4A6E; --c-secondary-lt:#EDF2F9;
    --c-accent:#C8412D; --c-accent-lt:#FDECEA;
    --c-text:#1A1918; --c-text-muted:#5C5750; --c-text-subtle:#9C9490;
    --c-success:#1E6B45; --c-success-lt:#E6F4ED;
    --c-warning:#7A4F00; --c-warning-lt:#FFF4DC;
    --c-error:#B91C1C; --c-error-lt:#FEE2E2;
    --c-chart-bar:#2C4A6E; --c-chart-bar2:#C5D8EE; --c-toggle-knob:#FFFFFF;
    --c-bullet-poor:#B8B8B8; --c-bullet-mid:#D0D0D0; --c-bullet-good:#E4E4E4;
    --c-bullet-border:#C8C8C8; --c-bullet-bar:#2C4A6E;
  }
  html,body,#root { background:var(--c-base); color:var(--c-text); min-height:100%; width:100%;
    font-family:var(--ff-sans); font-size:var(--text-base); -webkit-font-smoothing:antialiased; }
  a { color:var(--c-secondary); text-decoration:underline; text-underline-offset:2px; }
  a:hover { color:var(--c-accent); }
  :focus-visible { outline:3px solid var(--c-accent); outline-offset:2px; border-radius:2px; }
  .ndfi-tgl-lbl { display:flex; align-items:center; cursor:pointer; flex-shrink:0; }
  .ndfi-tgl-inp { position:absolute; opacity:0; width:0; height:0; }
  .ndfi-tgl-track {
    position:relative; width:64px; height:32px;
    background:var(--c-secondary); border-radius:16px;
    border:1px solid var(--c-secondary); flex-shrink:0;
    display:flex; align-items:center; justify-content:space-between;
    padding:0 6px;
  }
  /* Sun and moon icons inside the track */
  .ndfi-tgl-track::before { content:'☀️'; font-size:14px; line-height:1; z-index:1; }
  .ndfi-tgl-track::after {
    content:'🌙'; font-size:14px; line-height:1; z-index:1;
  }
  /* Sliding knob — covers the inactive icon */
  /* Light mode: knob RIGHT covers moon → shows sun */
  /* Dark mode (checked): knob LEFT covers sun → shows moon */
  .ndfi-tgl-knob {
    position:absolute; top:3px; left:37px;
    width:24px; height:24px; border-radius:50%;
    background:var(--c-base);
    transition:transform 0.28s cubic-bezier(0.34,1.56,0.64,1);
    z-index:2; pointer-events:none;
    border:1px solid var(--c-border);
  }
  .ndfi-tgl-inp:checked + .ndfi-tgl-track .ndfi-tgl-knob { transform:translateX(-34px); }
  .ndfi-tgl-inp:focus-visible + .ndfi-tgl-track { outline:3px solid var(--c-accent); outline-offset:2px; border-radius:16px; }
`;
const SPONSOR_SRC = `data:image/svg+xml;base64,`;
// ─── CSS VARIABLE TOKENS — all components use these, zero hardcoded values ────
const C = {
  base:"var(--c-base)",surface:"var(--c-surface)",surface2:"var(--c-surface-2)",
  border:"var(--c-border)",text:"var(--c-text)",muted:"var(--c-text-muted)",
  subtle:"var(--c-text-subtle)",accent:"var(--c-accent)",accentLt:"var(--c-accent-lt)",
  secondary:"var(--c-secondary)",secondaryLt:"var(--c-secondary-lt)",
  success:"var(--c-success)",successLt:"var(--c-success-lt)",
  warning:"var(--c-warning)",warningLt:"var(--c-warning-lt)",
  error:"var(--c-error)",errorLt:"var(--c-error-lt)",
  chartBar:"var(--c-chart-bar)",chartBar2:"var(--c-chart-bar2)",
  bulletPoor:"var(--c-bullet-poor)",bulletMid:"var(--c-bullet-mid)",bulletGood:"var(--c-bullet-good)",bulletBorder:"var(--c-bullet-border)",bulletBar:"var(--c-bullet-bar)",
};
// Typography — 0.875rem (14px) is the absolute floor, never go below
const T = {
  sm:"var(--text-sm)",base:"var(--text-base)",h3:"var(--text-h3)",
  h2:"var(--text-h2)",h1:"var(--text-h1)",mono:"var(--ff-mono)",sans:"var(--ff-sans)",
};
// Spacing — all 8pt multiples
const SP = {1:"var(--sp-1)",2:"var(--sp-2)",3:"var(--sp-3)",4:"var(--sp-4)",6:"var(--sp-6)",8:"var(--sp-8)"};

// ─── GLOBAL STYLE + THEME INIT ────────────────────────────────────────────────
const GlobalStyle = () => {
  useEffect(() => {
    const id="ndfi-css";
    if (!document.getElementById(id)) {
      const s=document.createElement("style"); s.id=id;
      s.textContent=GLOBAL_CSS; document.head.appendChild(s);
    }
    const saved=localStorage.getItem("ndfi-theme");
    const dark=window.matchMedia("(prefers-color-scheme: dark)").matches;
    document.documentElement.setAttribute("data-theme",saved??(dark?"dark":"light"));
  },[]);
  return null;
};

// ─── THEME TOGGLE ─────────────────────────────────────────────────────────────
const ThemeToggle = () => {
  const [dark,setDark] = useState(()=>{
    if (typeof window==="undefined") return true;
    const s=localStorage.getItem("ndfi-theme");
    return s?s==="dark":window.matchMedia("(prefers-color-scheme: dark)").matches;
  });
  const toggle = () => {
    const next=!dark; setDark(next);
    document.documentElement.setAttribute("data-theme",next?"dark":"light");
    localStorage.setItem("ndfi-theme",next?"dark":"light");
  };
  return (
    <label className="ndfi-tgl-lbl" aria-label={dark?"Switch to light mode":"Switch to dark mode"}>
      <input type="checkbox" role="switch" aria-checked={dark} checked={dark} onChange={toggle} className="ndfi-tgl-inp" />
      <span className="ndfi-tgl-track" aria-hidden="true"><span className="ndfi-tgl-knob" /></span>
      <span aria-live="polite" style={{position:"absolute",width:1,height:1,overflow:"hidden",clip:"rect(0,0,0,0)"}}>
        {dark?"Dark mode active":"Light mode active"}
      </span>
    </label>
  );
};

