const LEARN_SECTIONS = [
  {id:"shadow",color:C.secondary,heading:"What is shadow banking?",
    body:"Shadow banking refers to credit intermediation that happens outside the traditional regulated banking system. Non-bank lenders perform many of the same functions as banks but without deposit insurance, Federal Reserve access, or the same capital requirements.",
    links:[{label:"FSB Global Shadow Banking Report",url:"https://www.fsb.org/2024/12/global-monitoring-report-on-non-bank-financial-intermediation-2024/"},{label:"Federal Reserve: Nonbank Financial Institutions",url:"https://www.federalreserve.gov/releases/z1/"},{label:"IMF: Shadow Banking Around the Globe",url:"https://www.imf.org/external/pubs/ft/sdn/2014/sdn1408.pdf"}]},
  {id:"why",color:C.accent,heading:"Why does bank-to-NDFI lending matter?",
    body:"Banks and shadow lenders are deeply interconnected. NDFIs borrow from banks to fund their own lending — creating a chain of leverage that traditional regulatory metrics don't fully capture. When NDFIs run into trouble, credit lines drawn from banks become losses on bank balance sheets.",
    links:[{label:"OFR Brief 26-02: Measuring Counterparty Exposures",url:"https://www.financialresearch.gov/briefs/2026/03/12/measuring-counterparty-exposures-private-credit/"},{label:"FDIC Banking Issues in Focus (Feb 2026)",url:"https://www.fdic.gov/analysis/bank-lending-nondepository-financial-institutions.pdf"},{label:"BIS Working Paper: Banks and Shadow Banks",url:"https://www.bis.org/publ/work924.htm"}]},
  {id:"frameworks",color:C.success,heading:"Key regulatory frameworks",
    body:"Three reporting systems capture different views. FDIC Call Reports are public quarterly filings by banks. The Federal Reserve's Form Y-14 is confidential and captures granular counterparty detail for stress testing. SEC Form PF is filed by private fund advisers and shows the fund-side view of borrowing.",
    links:[{label:"FFIEC Central Data Repository",url:"https://cdr.ffiec.gov/public/"},{label:"FR Y-14Q Form Details",url:"https://www.federalreserve.gov/apps/reportingforms/Report/Index/FR_Y-14Q"},{label:"SEC Form PF Instructions",url:"https://www.sec.gov/divisions/investment/pfrd/pf-instructions.pdf"}]},
  {id:"glossary",color:"#A893D4",heading:"Glossary",body:null,links:[],glossary:[
    {term:"NDFI",def:"Non-Depository Financial Institution. Any lender that does not hold federally insured deposits. Includes mortgage companies, private credit funds, consumer finance companies, and others."},
    {term:"Tier 1 Capital",def:"A bank's highest-quality capital buffer — common equity and retained earnings that can absorb losses before the bank becomes insolvent."},
    {term:"Unfunded Commitments",def:"Credit lines, revolving facilities, and loan commitments banks have agreed to extend but that haven't been drawn yet."},
    {term:"QoQ Growth",def:"Quarter-over-quarter growth. The percentage change in a metric from one quarter to the next."},
    {term:"Delinquency Rate",def:"The percentage of loans that are 30 or more days past due."},
    {term:"PIK (Payment-in-Kind)",def:"A loan structure where interest is paid by issuing more debt rather than cash. Can mask deteriorating credit quality."},
    {term:"GSIB",def:"Global Systemically Important Bank. Designation given to the largest banks whose failure would pose risks to the global financial system."},
    {term:"Private Credit",def:"Loans made by non-bank lenders directly to companies, often to fund leveraged buyouts."},
    {term:"CAGR",def:"Compound Annual Growth Rate. The rate at which a quantity would have grown if it grew at a steady annual rate."},
  ]},
  {id:"reading",color:C.muted,heading:"Further reading",
    body:"Books, papers, and journalists covering the intersection of banking, private credit, and systemic risk.",
    links:[{label:"'Other People's Money' — John Kay",url:"https://www.johnkay.com/other-peoples-money/"},{label:"'The End of Alchemy' — Mervyn King",url:"https://wwnorton.com/books/the-end-of-alchemy/"},{label:"FDIC 2025 Risk Review",url:"https://www.fdic.gov/analysis/2025-risk-review.pdf"},{label:"S&P Global: NDFI Lending Q4 2025",url:"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2026/2/us-banks-ndfi-lending-pace-reaccelerates-in-q4-2025-98612159"}]},
];

